import EarlGrey from "./assets/teaBilder/EarlGrey.png";

export default function Buttons() {
  const teas = [
    { name: "Earl Grey", image: EarlGrey }
  ];

  return (
    <div>
      {teas.map((tea, index) => (
        <button key={index}>
          {tea.name}
          <img src={tea.image} alt={tea.name} />
        </button>
      ))}
    </div>
  );
}
